{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "SC-4453, a large glycoside, showed the lowest brain concentration among tissues at steady state in guinea pigs, demonstrating that this class of polar glycosides is restricted by the blood-brain barrier.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Mithramycin, a large glycosylated polyketide, achieved only a 0.12 CSF:plasma ratio in monkeys and little brain exposure, directly supporting poor CNS access for structurally related glycosylated natural products.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Digitoxin, a cardiac glycoside, had a very low CSF/plasma ratio of 0.01-0.03 in dogs, indicating that glycosidic polarity and size prevent meaningful brain penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Methylprednisolone, a moderately lipophilic steroid, showed only slow transporter-mediated blood-to-brain transport in guinea pigs, illustrating that even less polar polycyclic molecules can have limited CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "A related glycosylated heterocycle showed negligible brain uptake in mice at 2 and 60 minutes, reinforcing poor CNS exposure for polar glycoside-like scaffolds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "DX-52-1, a polycyclic natural-product analogue, had a brain-to-blood ratio of about 0.02 in mice, indicating very poor blood-brain barrier crossing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "CMT-3, a lipophilic tetracycline analogue, showed brain accumulation of 4 µg/g in rats, providing some contradictory evidence that certain polycyclic polar molecules can penetrate; however, its lower transfer relevance and greater lipophilicity limit its applicability to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C10"],
      "claim": "A glucose-conjugated compound reached 3.1 nmol/g in rat brain via GLUT1-mediated transport, but the query bears an aminosugar rather than a glucose moiety, so this transporter-dependent positive result is not directly transferable.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a large, highly polar, ionizable glycosylated anthracycline-like molecule with physicochemical properties strongly unfavorable for passive BBB permeation. The most transferable experimental analogues—large glycosides and glycosylated polycyclic natural products—consistently show poor brain and CSF penetration. The few permeable analogues are structurally less relevant and depend on lipophilicity or specific glucose-transporter recognition not applicable to the query. Overall, meaningful CNS access after systemic administration is unlikely.",
  "evidence_gaps": [
    "No direct brain, plasma, CSF, or perfusion measurement exists for the exact query molecule.",
    "Potential active uptake by nutrient transporters other than GLUT1 has not been experimentally assessed for the query.",
    "Species differences in BBB transporters and metabolism may affect quantitative translation.",
    "The query's aminosugar may have different transporter interactions than the glucose or neutral sugar moieties in the evidence compounds."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

